var t=`0144-spas-soup`;var n=`world-0144`;var s=`AM`;var a=`western-asia`;var r=4;var o=68;var l={en:`Spas Soup`,ua:`Суп спас`};var g={en:`A classic dish from Armenia, featuring wheat berries, plain yogurt, chicken egg, mint. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Вірменія. Основні складники: зерна пшениці, натуральний йогурт, куряче яйце, м'ята. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 45 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 45 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:45,i:[[`wheat-berries`,145,`g`],[`water`,650,`ml`]]},{en:`Whisk or whip the listed ingredients to a smooth, light consistency, then keep cool until needed.`,ua:`Збийте зазначені складники до гладкої легкої консистенції, після чого зберігайте в прохолоді до використання.`,t:[`whipping`],m:5,i:[[`plain-yogurt`,730,`g`],[`all-purpose-flour`,25,`g`],[`chicken-egg`,1,`pcs`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 15 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 15 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:15,i:[[`chicken-stock`,350,`ml`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`mint`,18,`g`],[`unsalted-butter`,35,`g`],[`table-salt`,null,`to_taste`]]}];var h={slug:t,id:n,country:`AM`,region:a,servings:4,minutes:68,title:l,text:g,steps:d};export{s as country,h as default,n as id,o as minutes,a as region,r as servings,t as slug,d as steps,g as text,l as title};